describe('Restore Archived Record', () => {
    beforeEach(() => {
        cy.visit('/records'); // Navigate to the records page
        cy.login(); // Assuming there's a custom command for login
    });

    it('should successfully restore an archived record', () => {
        cy.get('.archived-records').within(() => {
            cy.get('.record-item').first().as('firstArchivedRecord');
            cy.get('@firstArchivedRecord').find('.restore-button').click();
        });

        cy.get('.notification').should('contain', 'Record restored successfully');
        cy.get('.active-records').should('contain', 'Restored Record Name'); // Replace with actual record name
    });

    it('should show an error when trying to restore a record that is not archived', () => {
        cy.get('.active-records').within(() => {
            cy.get('.record-item').first().as('firstActiveRecord');
            cy.get('@firstActiveRecord').find('.restore-button').click();
        });

        cy.get('.notification').should('contain', 'Cannot restore a record that is not archived');
    });
});
